#include <QDir>
#include <QFileInfo>
#include <QTextStream>
#include <QDebug>

int main(int argc, char *argv[])
{
    // Set directory path
    QString directoryPath = "./";

    // Create QDir object with directory path
    QDir directory(directoryPath);

    // Filter files to show only regular files
    directory.setFilter(QDir::Files | QDir::NoSymLinks);

    // Sort files in alphabetical order, start from upper letters
    directory.setSorting(QDir::Name | QDir::Reversed);

    // Get list of all files in directory
    QFileInfoList fileList = directory.entryInfoList();

    // Loop through each file in list
    for (int i = 0; i < fileList.size(); i++)
    {
        // Get file info for current file
        QFileInfo fileInfo = fileList.at(i);

        // Open file for reading
        QFile file(fileInfo.filePath());
        if (!file.open(QIODevice::ReadOnly | QIODevice::Text))
        {
            qDebug() << "Failed to open file:" << fileInfo.fileName();
            continue;
        }

        // Read contents of file
        QTextStream stream(&file);
        QString fileContents = stream.readAll();

        // Close file
        file.close();

        // Print contents of file
        qDebug() << "File contents:" << fileContents;
    }

    return 0;
}
